///
/// # use pagetray_sdk::server::plugin::{Plugin, Scoped};
/// # use pagetray_sdk::scope;
/// # struct MockPlugin;
/// # impl<S, Op, T> Plugin<S, Op, T> for MockPlugin { type Output = u32; fn apply(&self, input: T) -> u32 { 3 } }
