/// # let scoped_b = Scoped::new::<ScopeB>(MockPlugin);
/// # let a = Plugin::<(), pagetray_sdk::operation_shape::CreatePage, u64>::apply(&scoped_a, 6);
/// # let b = Plugin::<(), pagetray_sdk::operation_shape::CreatePage, u64>::apply(&scoped_b, 6);
